import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Class: ClientPacketRegistry","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/client/classes/ClientPacketRegistry.md","filePath":"api/@jsprismarine/client/classes/ClientPacketRegistry.md"}`),a={name:`api/@jsprismarine/client/classes/ClientPacketRegistry.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/client</a> / ClientPacketRegistry</p><h1 id="class-clientpacketregistry" tabindex="-1">Class: ClientPacketRegistry <a class="header-anchor" href="#class-clientpacketregistry" aria-label="Permalink to “Class: ClientPacketRegistry”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L65" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:65</a></p><p>Which packet class handles which id, with no server anywhere in the signature.</p><p>The server&#39;s registry is built around a <code>Server</code> - it logs through it, and its handlers take it as their second argument - which is exactly why the client could not reuse it. This one maps ids to codecs and stops there; what to <em>do</em> with a decoded packet is the caller&#39;s business, and on the client that answer differs between the login sequence, the game session and a bot&#39;s behavior script.</p><p>An id with no class registered is not an error. A client meets packets it has no use for from its first join - the server sends crafting data and biome definitions before the player can move - and refusing to proceed until all of them are implemented would mean implementing all of them before anything works at all.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ClientPacketRegistry</strong>(): <code>ClientPacketRegistry</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientPacketRegistry</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="decode" tabindex="-1">decode() <a class="header-anchor" href="#decode" aria-label="Permalink to “decode()”">​</a></h3><blockquote><p><strong>decode</strong>(<code>buffer</code>): <a href="./../interfaces/DecodedPacket.html"><code>DecodedPacket</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L96" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:96</a></p><p>Decodes one packet, or returns null if nothing is registered for its id.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="buffer" tabindex="-1">buffer <a class="header-anchor" href="#buffer" aria-label="Permalink to “buffer”">​</a></h5><p><code>Buffer</code></p><p>a single packet as it came out of the batch, header included.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../interfaces/DecodedPacket.html"><code>DecodedPacket</code></a> | <code>null</code></p><hr><h3 id="getunknownids" tabindex="-1">getUnknownIds() <a class="header-anchor" href="#getunknownids" aria-label="Permalink to “getUnknownIds()”">​</a></h3><blockquote><p><strong>getUnknownIds</strong>(): <code>number</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L115" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:115</a></p><p>Every id seen that nothing was registered for.</p><p>Kept because it is the honest measure of how much of the protocol is implemented, and because it is what a &quot;what is this server sending that we ignore?&quot; question needs.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code>[]</p><hr><h3 id="has" tabindex="-1">has() <a class="header-anchor" href="#has" aria-label="Permalink to “has()”">​</a></h3><blockquote><p><strong>has</strong>(<code>id</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L87" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:87</a></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="register" tabindex="-1">register() <a class="header-anchor" href="#register" aria-label="Permalink to “register()”">​</a></h3><blockquote><p><strong>register</strong>(<code>constructor</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L73" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:73</a></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="constructor-1" tabindex="-1">constructor <a class="header-anchor" href="#constructor-1" aria-label="Permalink to “constructor”">​</a></h5><p><a href="./../type-aliases/PacketConstructor.html"><code>PacketConstructor</code></a></p><p>the packet class; its id is read off a throwaway instance, because <code>NetworkPacket</code> declares the id as an instance getter rather than a static.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="registerall" tabindex="-1">registerAll() <a class="header-anchor" href="#registerall" aria-label="Permalink to “registerAll()”">​</a></h3><blockquote><p><strong>registerAll</strong>(<code>constructors</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L83" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:83</a></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="constructors-1" tabindex="-1">constructors <a class="header-anchor" href="#constructors-1" aria-label="Permalink to “constructors”">​</a></h5><p>readonly <a href="./../type-aliases/PacketConstructor.html"><code>PacketConstructor</code></a>[]</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="readpacketid" tabindex="-1">readPacketId() <a class="header-anchor" href="#readpacketid" aria-label="Permalink to “readPacketId()”">​</a></h3><blockquote><p><code>static</code> <strong>readPacketId</strong>(<code>buffer</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2d9d9266a761a38ca89c3608652373fb863b6e42/packages/client/src/net/ClientPacketRegistry.ts#L126" target="_blank" rel="noreferrer">packages/client/src/net/ClientPacketRegistry.ts:126</a></p><p>Peeks the id without consuming anything.</p><p>The header is an unsigned varint, so the id is not simply the first byte - which is how the server reads it, and which works only because every id it handles happens to fit in seven bits or to have a low byte that collides with nothing.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="buffer-1" tabindex="-1">buffer <a class="header-anchor" href="#buffer-1" aria-label="Permalink to “buffer”">​</a></h5><p><code>Buffer</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p>`,69)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};